referenceSolutions.javascript:
export function solve(left, right) {
  if (left.status === "rejected") return left;
  if (right.status === "rejected") return right;
  const a = left.value,
    b = right.value;
  let value;
  if (typeof a === "number" && typeof b === "number") value = a + b;
  else if (typeof a === "string" && typeof b === "string") value = a + b;
  else if (Array.isArray(a) && Array.isArray(b)) value = [...a, ...b];
  else if (
    a !== null &&
    b !== null &&
    typeof a === "object" &&
    typeof b === "object" &&
    !Array.isArray(a) &&
    !Array.isArray(b)
  )
    value = { ...a, ...b };
  else return { status: "rejected", value: "incompatible" };
  return { status: "fulfilled", value };
}

